      "phase": "现实开场 / 老年相遇",
      "prompt": "首帧 复古灰褐色水彩质感的室内场景。 镜头面对一面古典立镜，镜子里只能看到老人下巴以下到胸口的位置，穿深色西装、马甲、白衬衫、领带。 老人刚整理完领带，双手已经从领口缓缓放下，停在身体两侧偏下的位置。 画面左侧有老照片和小摆件，右后方能看到钢琴。 整体安静、克制、怀旧，室内柔和漫射光，气氛沉静。 运动过程 保持第一视角逻辑，不要让人物走上前，也不要出现完整正脸。 镜头在原地轻微停顿一瞬，随后像`我`本人自然转身一样，缓慢、平稳地把视线从镜子方向转向钢琴方向。 这个转向是原地缓缓转身 / 视线转移，不是向前行走，不是推进冲刺，不是大幅摇镜头。 在转身过程中，镜中人物和梳妆台逐渐离开画面主体，钢琴逐渐进入视觉中心。 镜头转动速度要慢，带一点人站在原地转身时的自然呼吸感与极轻微晃动。 尾帧 画面最终停在钢琴上。 一架复古三角钢琴成为主体，琴凳在前，琴谱摊开，室内窗光柔和，整体延续灰褐色、低饱和、水彩纸张肌理。 钢琴处于画面中心偏右或中心位置，成为明确视觉落点。",
