      "phase": "校园回忆",
      "prompt": "以第一张图为首帧，第二张图为尾帧。镜头保持平稳，继续缓慢横向转动，画面重心持续移向窗户。自然转动，而不是平移。女孩逐渐从画面右侧退出，桌面、课本和手部也随之慢慢退出画面，不要突然消失。窗框、窗外朦胧树影和窗边墙面逐渐占据主要画面，最终停在以整扇窗户为主体的构图。整体过程自然、连贯、安静，不要推拉，不要跳切，不要新增多余动作，不要改变原有风格和光线。",
