      "height": 600,
      "phase": "校园回忆",
      "prompt": "保持第一视角不变。 镜头从课本位置开始，缓慢向上抬起视线，视角自然上移，从书页逐渐看到女孩递书的手、上半身，最后停在女孩的正脸和整体形象上。 整个过程平稳、连续，不切镜，不突然推进拉远。 女孩在镜头抬起过程中保持自然注视，等镜头停到她的脸后，她先轻轻微笑，然后俏皮地、幅度很小地歪一下头，动作克制，自然停住。不要切镜，不要突然摇晃，不要镜头乱飘，不要夸张表情，不要嘴巴乱动，不要人物身体大幅晃动，不要手部变形，不要多出手指，不要课本乱翻页，不要出现第二个人，不要改变第一视角，不要变成第三视角，不要风格漂移，不要过强动画感。",
