      "height": 630,
      "phase": "校园回忆",
      "prompt": "保持第一视角固定不变。 画面从第一张开始，女孩正把书递向镜头。镜头位置稳定，不切镜，不突然推拉。接下来，女孩先用原本递书的那只手，将课本轻轻放低、放回桌面，让书自然落稳在画面前方。这个动作要平缓、连贯，不要突然松手，不要像砸下去。 在书放稳之后，女孩的另一只手从身体另一侧自然伸出来，手里拿着一根棒棒糖。她把棒棒糖轻轻放到课本打开的页面上，并用棒棒糖轻轻压住书页，动作温柔、克制，像一个小小的玩笑或暗示。 整个过程中，女孩始终自然地看着`我`，表情柔和，带一点轻松的笑意。等棒棒糖放稳之后，她停顿一瞬，再对着`我`露出一个更明确一点的微笑，但不要夸张，不要大笑，不要故意卖萌。 头部保持基本端正，不要明显歪头，只允许非常轻微、自然的神态变化。身体姿态自然，肩膀比例正常，双臂动作清楚，左右手分工明确，不要混成一只手完成所有动作。 整体节奏要像真实人物在桌前完成一个小动作：放书 → 另一只手拿出棒棒糖 → 压在书上 → 看着我笑。 全程动作幅度小，气质安静、温柔、带一点俏皮。不要切镜，不要镜头乱晃，不要突然推进，不要突然拉远，不要人物突然跳动，不要课本乱翻页，不要多出手指，不要手部变形，不要双手混乱交叉，不要把棒棒糖变成别的东西，不要让同一只手既放书又拿棒棒糖，不要夸张歪头，不要肩膀过宽或塌陷，不要表情过度卖萌，不要张嘴大笑，不要改变第一视角，不要风格漂移，不要一直咧着嘴笑。先低头，目光跟随着棒棒糖，最后放到桌面上的时候抬眸微笑",
