      "prompt": "保持第一视角手持录像机，延续首帧画面。 手和录像机始终稳定在前景，保持原有握持方式，只允许轻微自然手持晃动。 镜头从当前拍摄前方道路的状态，自然、缓慢地向右转动，像`我`继续拿着录像机拍右边。 转动过程中不要切镜头，不要突然跳变，不要突然拉近，不要大幅抖动。 道路、树木、建筑和路边景物随着镜头转向自然横向移动，录像机屏幕里的画面也同步变化。 当镜头转到右边后，女孩从画面右侧俏皮地探头入镜。 她不是突然僵硬地出现，而是像发现镜头在拍，带一点灵动和玩笑感地把头和上半身探进来。 动作要有连续感：先轻轻探入，再靠近一点，对着镜头自然地笑。 表情要真实、生动、轻松，带一点调皮和青春感，不要僵硬，不要`AI假笑`，不要木。 头发可以有轻微跟随动作的摆动，体现动态感。 女孩与之前的人物保持同一人设和气质。 整体节奏是： 先拍前方 → 镜头向右转 → 女孩探头入镜并自然一笑。",
