      "phase": "校园回忆",
      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的转场视频。保持同一校园道路、同一机位延续、同一水彩纸张肌理与柔和怀旧色调。镜头为第一视角，开始时`我`正举着一台小型录像机拍摄前方，女孩从画面右侧探头入镜，带一点恶作剧成功后的俏皮感，但此时不要直接进入掩面而笑的状态，也不要一开始就笑得很满。她更像是在偷偷观察`我`的反应，眼神带一点轻快、调皮、得逞后的开心，嘴角可以有轻微笑意，但表情要克制自然。 随后，`我`缓慢放下手中的录像机，录像机和手自然下移并退出画面，不要突然消失，不要跳切。镜头轻微而稳定地朝女孩的方向落过去，视线自然集中到她身上，让女孩逐渐成为画面主体。女孩保持站在画面右侧偏前的位置，身体微微前倾，看向`我`，先维持一种带点俏皮、又有点试探地看`我`反应的状态。 当`我`的录像机放下、视线真正落到她身上之后，女孩才像是被`我`的反应逗到，或者因为被认真看见而有一点不好意思。这个时候她的情绪再自然转化为笑。 她先出现一瞬间微微忍不住笑的感觉，然后再抬起一只手，轻轻遮住嘴，动作是顺着情绪自然发生的，不要一开始就把手放到脸上。遮的是嘴部附近，不是整张脸捂住。笑意是在掩嘴的动作过程中自然浮现并展开，是一种柔软的、害羞的、觉得`我`很可爱的笑，不是提前摆好的笑脸。眼睛要慢慢带出笑意，表情灵动自然，有一点少女的俏皮和害羞，不要僵硬，不要AI感，不要诡异夸张。 整体动作幅度克制，风吹发丝和衣角可以有轻微动态，树影与环境保持安静自然。不要改变场景布局，不要大幅移动机位，不要突兀拉近，不要额外增加人物。最终停在图二那种状态：录像机已经放下，女孩成为主体，手轻轻掩住嘴，笑意在这一动作之后自然形成并停住。",
