      "prompt": "以图一为首帧，图二为尾帧，生成一段自然连贯的转场视频。 镜头保持第一视角，`我`始终坐在桌前，右手仍放在键盘上。开头先延续图一动作：女孩放下水杯后，手在杯边短暂停留一下，然后慢慢收回，退出画面右侧。收手过程中，杯子保持稳定，桌面其他物体不要变化。 随后，`我`的视角开始自然转头，从桌面和窗外方向慢慢转向右侧，像坐着的人在椅子上转头看过去。镜头运动要平稳、缓慢，带一点真实的人体视角惯性，不要突然跳转，不要明显推拉。 随着转头，电脑桌、键盘等元素逐渐退出画面，女孩慢慢进入主体位置。最终镜头停在图二构图：女孩站在`我`面前，成为画面主体，微微俯身，看向`我`，表情是忧虑、心疼、温柔克制，带一点担心。 保持人物、服装、发型、雨夜窗景、室内灯光连续一致。不要新增无关物品，不要改变空间结构，不要夸张表演。整体节奏安静、生活化、自然。 动作顺序：放稳水杯 → 手收回 → `我`转头 → 看到女孩。",
