      "phase": "现实开场 / 老年相遇",
      "prompt": "以这张图为首帧，生成一段自然连贯的第一视角吃饭视频。 镜头保持`我`坐着低头吃饭的主观视角，画面中只有饭碗、双手和筷子。左手稳稳端着饭碗，右手拿着筷子，动作自然、日常、平静。 先用筷子从碗里夹起一小团米饭，动作轻微停顿一下，然后右手把米饭缓慢送向自己。随着筷子向上移动，米饭逐渐靠近画面上方，在接近`嘴边`时自然离开画面并消失，被第一视角遮挡，不要出现嘴巴、脸部或吃进去的画面。 之后筷子自然回落到碗中，再进行一次普通的小幅夹饭动作，整体节奏像平常安静吃饭一样。左手端碗基本稳定，只有轻微自然晃动。镜头也保持稳定，只带一点轻微人体呼吸感和手部动作带来的细小晃动。 不要新增其他人物，不要出现女人和孩子，不要出现其他菜、杯子等元素。保持木桌、暖色室内灯光、夜晚居家氛围、低饱和、克制、水彩纸张质感。",
