      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的转场视频。保持同一餐桌场景、同一第一视角机位、同一人物位置不变。 动作顺序： 女生先用勺子喂孩子，勺子停在孩子嘴边片刻； 然后女生把勺子自然收回，手从孩子嘴边往桌上的菜盘移动，准备给孩子再舀一勺菜； 注意： 不要跳切，不要突然变脸，不要大幅改变构图； 女生的发型、服装、手部、孩子位置、桌面摆设都保持稳定； 孩子基本保持坐着看妈妈的状态，只做轻微自然反应； 整体动作节奏平稳、生活化",
