      "phase": "现实开场 / 老年相遇",
      "prompt": "以这张图为首帧生成视频。 这不是重画场景，是让画面产生“我”正在小区里一步一步慢慢向前走的感觉。 画面保持第一视角，只看前方的小区道路。道路、楼栋、树、路灯、湿润地面和夜晚氛围都保持不变。不要新增人物，不要出现旁边同行者。 镜头向前缓慢移动，速度很慢，像老人饭后在小区里散步。移动不是平滑漂浮，而是有轻微的步伐起伏：每走一步，画面有很轻的上下晃动和身体惯性，节奏缓慢、稳定、克制。不要快速推进，不要突然拉近，不要大幅摇晃。 前方路面上的水光和路灯倒影随着步伐慢慢接近，树影、楼栋和路灯在两侧自然后退。画面始终保持安静、低饱和、夜晚、小区、湿润路面的氛围。 整体感觉是：我一个人在夜晚小区里，慢慢往前走，一步一步，很安静，很缓，有一点晚年的疲惫和恍惚感。 环境音效： 加入很轻的夜晚小区环境声，远处有微弱风声、树叶轻响、远处楼栋生活声和很淡的城市底噪。地面微湿，可以有轻微脚步声，步伐缓慢，鞋底踩在湿润路面上发出很轻的`嗒、嗒`声。不要加入明显音乐，不要加入人声，不要加入夸张雨声。环境声要克制、真实、安静。",
