      "phase": "现实开场 / 老年相遇",
      "prompt": "这张图不是重画场景，是调整`我`的视线方向和画面主体位置。 `我`原本是在往前走，只看前方。 现在改为：我在行走途中，正在慢慢回头。 这不是已经完全转过去的状态，而是转头到一半的状态。 也就是说，画面里仍然保留一部分原本前方道路的感觉，但视线已经明显往后方偏过去。 原本前方笔直的小区道路、楼栋、树、路灯这些元素，不要完全消失，而是作为转头途中仍能看到的一部分背景，逐渐退到一侧。 不要把所有景物平均铺开。 允许道路方向发生偏转，允许原本正前方的路变成斜向一侧，做出视线正在转过去的感觉。 画面主体开始从`空的小区前路`变成`身后那个老人`。 她要出现在画面中后部偏右（或偏左），不是正中央顶格站着，而是像在`我`回头过程中逐渐进入视线。 她仍然是在走路，不是站着摆拍。 她走在小区路上，步子小，姿态慢，身体略微前倾，像老人走路。 她是那个女孩的老年版，要有老年特征，但保留原本的五官底子和温柔气质。 她此刻还没有明显笑出来，或者只是嘴角刚刚有一点点松动。 重点是：她先是安静地走着，在`我`回头看到她之后，情绪才开始有一点变化。 所以这一张图里，她更接近`被看见的前一刻 / 刚被看见的那一刻`。 `我`身边不要有人。 不要出现陪同者。 背景楼栋、树、灯光、湿润路面都保留原本小区夜晚氛围，但弱化为陪衬。 重点是做出一种： 我本来往前走，走着走着，慢慢回头，视线转过去，开始看见那个年老的她也在身后慢慢走着。 保持原图一致的夜晚小区氛围、低饱和、安静、克制、水彩纸张质感。",
