      "prompt": "保持首尾帧的同一场景与同一风格不变。 老人沿着小区湿润的路面继续慢慢向前走，步子小，动作稳，身体微微前倾，手里提着布袋，布袋随着走路有轻微摆动。 一开始她的表情是平静的、安静的，没有明显笑意，只是自然地往前走。 走的过程中，她注意到`我`在看她，于是目光慢慢落到`我`身上，眼神变得更柔和。 随后，她的嘴角轻轻地、很克制地上扬，露出一个很淡、很温柔的微笑。 不是突然笑开，也不是夸张表情，而是那种看到`我`之后，安静地、慢慢地笑了一下。 她始终保持走路状态，不要停下来摆拍。 笑意是在走路途中自然发生的。 整体节奏要慢，要有`一步一步、缓慢靠近`的感觉。 不要跳帧，不要突然位移，不要夸张镜头运动。 保持安静、克制、低饱和的情绪。 加入环境音效： 夜晚小区的细微环境声、很轻的脚步声、湿润路面的踩踏声、远处若有若无的风声、树叶轻响、安静的小区氛围声。 整体音效要轻，不要喧宾夺主。",
