      "prompt": "保持同一婚礼教堂场景、同一机位、同一第一视角、同一柔和水彩纸张肌理、米白暖调与安静温柔氛围。 女孩始终站在原地，不再继续往前走，只是将左手自然伸向`我`。 `我`先用一只手轻轻握住、托住女孩伸出的左手，随后另一只手拿着戒指，缓慢、郑重地对准女孩左手无名指，为她戴上戒指。 在戴戒指的过程中，女孩要适当地微微低头，自然把目光落到两人的手部动作上，神情柔和，嘴角带轻微笑意，动作克制、安静、有仪式感。 镜头整体保持稳定，可以只有很轻微的靠近感，用来强调手部细节与情绪流动。 不要让女孩继续走动，不要大幅度镜头运动，不要突然切换，不要夸张表情，不要手部畸形，不要戴错手指。",
