      "height": 520,
      "phase": "婚礼",
      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的过渡视频。保持同一婚礼教堂、同一女孩、同一婚纱头纱、同一暖米白低饱和水彩纸张质感、同一第一视角。 视频开始时，女孩正伸着手，我刚刚为她戴上戒指。 她先低头轻轻看一眼自己手上的戒指，情绪被触动，呼吸微微停顿一下。 然后她再慢慢抬眼看向我，表情不是一直保持微笑，而是从克制的浅笑，自然过渡到被打动后的湿润、轻微发酸、带一点想哭却在忍住的笑意。 她的眼神要有变化：先是安静、柔软，随后眼眶微微泛红或泛泪光，笑意变得更轻、更柔，不是傻笑，不是一直咧着嘴。 嘴角可以轻轻收一点，再缓慢松开，像情绪上来之后的温柔失守。 与此同时，我的双手自然松开她的手，从戴戒指的位置缓缓退开，放低一点，再轻轻向两侧打开，形成迎接她靠近的姿态。动作要自然，不要突然弹开，不要夸张张手。 女孩随后轻轻向前迈近一步，身体微微前倾，朝我靠近。她一边靠近，一边慢慢抬起双臂，向我伸来，动作温柔，不急，不扑，不夸张。 镜头保持严格第一视角，轻微向前迎上她，像我也下意识向她靠近。 最终自然过渡到尾帧：女孩已经更近地站在我面前，双臂张开，准备拥抱我，眼神温柔、湿润、安心，带有婚礼当下被深深打动后的情绪余波。 整体节奏要柔和、克制、连贯，重点是**`戴上戒指后，女孩先被触动，再慢慢靠近，最后张开双臂准备拥抱`**。 不要第三人称，不要婚礼合照感，不要突然跳切，不要僵硬摆拍，不要一直固定笑容。",
