      "height": 560,
      "phase": "医院",
      "prompt": "以这张窗帘图为首帧，生成一段自然连贯的短视频。保持同一病房窗边场景、同一暖米白低饱和水彩纸张质感、同一夜晚病房氛围。画面开始时是正常视野，没有任何眨眼遮挡，镜头安静地看着窗边轻轻摆动的浅色窗帘，整体节奏缓慢、克制、安静。 随后，保持第一视角主观感，像`我`在病床旁看着窗帘，情绪沉重又疲惫，开始很慢地眨眼。眨眼遮挡不是突然出现，而是从画面上方和下方非常缓慢地向中间靠拢，像眼皮一点一点合上。遮挡过程要自然柔和，不要机械，不要突兀，不要像硬切黑幕。窗帘在这个过程中仍然轻轻晃动，夜晚病房里的暖色光线也仍然存在，但随着眼皮逐渐闭合，能看到的画面越来越少。 最后，眨眼完全合上，整个画面自然进入彻底黑暗。结尾停留在全黑状态片刻，形成情绪上的收束。整体不要快，不要夸张，不要特效感太强，要像一个人真实地、疲惫地慢慢闭上眼。",
