      "phase": "医院",
      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的转场视频。 保持同一病房环境、同一暖米白低饱和水彩纸张质感、同一夜晚氛围、同一第一视角。 开始时，`我`的视线处于半眨眼状态，画面上下被眼皮遮挡，视野发闷、模糊，像刚从短暂失神中回过神来。随后眼皮缓慢抬起，遮挡自然向上和向下退去，视野一点点打开，不要突然跳开，不要闪切。与此同时，`我`的视线轻微清醒、重新聚焦，慢慢意识到前方的病床区域已经空了。 镜头保持第一视角，带一点趴在床边后刚抬眼的迟缓感，然后在睁眼过程中轻微抬起与稳定下来。床沿、被子、窗帘和病房空间逐渐完整进入视野。整个过程要有一种刚睁开眼、先愣住、随后察觉不对的感觉，动作克制、缓慢，但带一点隐隐的不安。 不要第三人称视角，不要额外人物突然出现，不要大幅度镜头摇晃，不要夸张特效，不要改变原有构图关系，只做从半眨眼遮挡到完全睁眼看清空病床的自然过渡。",
