      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的转场视频。 保持同一病房场景、同一暖米白低饱和水彩纸张质感、同一夜晚氛围、同一第一视角。 开始时，镜头处于`我`趴在病床边后的主观视角，画面前景保留一部分模糊的手臂与床边位置，视线朝向窗帘与窗户方向，状态安静、迟缓，像刚刚抬起眼睛。随后，`我`的视线慢慢转动，不要慌张，不要猛地甩头，也不要剧烈摇晃，而是带着一点疲惫和发愣感，缓慢地从窗边方向转向病床方向。 转动过程中，镜头轻微抬起并平稳移动，像人从趴着的姿势里慢慢清醒过来，视线一点点离开窗帘，掠过床栏，最后自然落到整张病床上。随着镜头转动，前景中的手臂可以逐渐退出或弱化，不要抢戏。尾帧里，病床完整进入视野，女孩已经不在，只剩下空掉的床铺与被子，形成一种安静、迟钝、慢半拍地察觉到`她不在了`的感觉。 整体节奏要克制、缓慢、连贯，不要做惊吓感，不要快速推拉，不要突然变焦，不要夸张表演，不要第三人称，不要额外人物出现。重点是从趴在床边看向窗边，到慢慢转头，看见空病床的第一视角过渡。",
