      "phase": "医院",
      "prompt": "以图一为首帧、图二为尾帧，生成一段自然连贯的转场视频。保持同一医院夜晚场景、同一暖黄低饱和水彩纸张质感、同一第一视角。 开始时，`我`正站在病房内，视线对着已经打开的房门，情绪是刚刚发现异常后的急切与不安。随后，`我`立刻快步往前赶，急匆匆地朝房门走去并穿过门口。镜头要带一点慌乱感，但不要剧烈晃动，不要夸张抖动，不要失控甩镜头。 穿过房门时，视线有一个明显的转头动作：先顺着门口往外冲，再迅速把视线转向外面的长走廊方向。这个转头要像人在着急寻找某个人时本能地扫过去，动作利落、偏快，但仍然自然连贯。 随后镜头继续向前一点点推进，完成从病房内部到病房外走廊的空间切换，最终稳定到图二那种正对长走廊的视角。走廊要显得空、安静、延伸感很强，重点是`我`冲出门后望见一整条长走廊的瞬间。 不要出现人物，不要突然跳切，不要第三人称，不要凭空生成多余手臂，不要过度旋转，不要强烈镜头摇晃，不要改变原有场景结构。整体节奏是：病房内发现不对劲 → 急匆匆冲出门 → 转头看向长走廊 → 画面落到空荡走廊。",
