      "height": 640,
      "phase": "医院",
      "prompt": "以图一为首帧、图二为尾帧。 第一视角，人物刚刚跌坐在医院走廊地面上，不是趴着。镜头保持低机位，视角略微倾斜，带一点刚跌坐后的轻微眩晕感。环境是空荡、昏暗、暖黄偏橙色灯光的医院走廊，两侧是病房门与扶手，地面有清晰反光，远处窗帘口透出微弱暖光，整体氛围压抑、安静、失神、带有喘息后的空茫感。 画面开始时，人物处于坐在地上的姿态，双腿屈起，穿焦黄色牛仔裤，左手自然放在左膝附近，手指略微弯曲，情绪低落、无力。随后，人物在原地缓缓抬起左手，不是起身，不是爬行，也不是撑地，而是像在失去之后下意识地、无力地向前伸出去触碰什么。 左手的动作是：从靠近膝盖的位置，慢慢向前、向上抬起，手背朝向镜头，手指逐渐张开，动作迟缓、克制、轻微颤抖。左臂穿着深灰色针织毛衣，袖口清楚可见。不要出现戒指。不要出现第二只手的动作重点。不要新增人物或其他元素。 镜头整体尽量稳定，只保留轻微呼吸感和微弱晃动，不要大幅移动，不要突然推拉摇移。重点表现从图一到图二之间，左手在空荡走廊中缓缓抬起、张开、停住的过程。 整体节奏缓慢，情绪是失去后的迟钝、难过、压抑、无助，像在回忆全部消失之后，独自坐在走廊里，朝空处伸出手。 风格保持电影感、细腻插画质感、柔和但克制、不恐怖、不夸张写实。医院走廊顶部的灯光在整个过程中要有轻微、不规律的闪烁，亮度偶尔忽明忽暗，像老旧医院灯管接触不稳时那种状态。 这种闪烁是克制的、细微的，不是恐怖片式疯狂爆闪，也不是完全熄灭，而是在暖黄偏橙色基调下，时不时轻轻跳动一下明暗。 地面的反光也要随着灯光闪烁产生细微变化，让整个空荡走廊更有一种失神、眩晕、情绪不稳的感觉。",
