      "phase": "医院",
      "prompt": "第一视角叙事。 开场是在昏暗空荡的医院走廊里，人物跌坐在地上，双腿屈起，穿焦黄色牛仔裤，左手抬起并自然张开，手背朝向镜头，手指修长，无名指上戴着一枚金色戒指。深灰色针织毛衣袖口清楚可见。人物处于刚刚失去重要之人后的低落状态，呼吸急促，情绪压抑、空茫、失神。 镜头从医院走廊的第一视角缓慢向左手推进，重点逐渐聚焦到无名指上的金色戒指。 在推进过程中，人物的左手有轻微颤抖，手指微微收放。 走廊里的暖黄色顶灯轻微闪烁，明暗忽强忽弱，地面反光也随灯光闪动，增强眩晕感和喘息感。 镜头整体保持轻微倾斜和不稳定感，像跌坐后尚未缓过神来。 当镜头推近到戒指附近时，戒指表面的反光逐渐变亮，成为转场媒介。 随着反光扩散，医院走廊的暖黄环境慢慢虚化、溶解，画面自然过渡到钢琴前的第一视角。 左手的姿态和位置在转场中尽量连贯延续，像同一只手从空中缓慢落回现实。 随后画面进入尾帧： 人物坐在钢琴前，第一视角看到自己的双手落在琴键上，开始弹奏。钢琴前方放着摊开的旧乐谱，环境安静克制，光线由走廊的暖橙色逐渐过渡为偏灰、柔和、安静的现实室内光。 双手最终稳定地放在琴键上， 整体节奏缓慢、克制、哀伤，有电影感，细腻插画质感，不要太写实，不要恐怖感。不要第三人称，不要新增人物，不要突然跳切，不要夸张镜头旋转，不要手部畸形，不要多手指，不要戒指位置错误，不要把戒指戴在食指或中指，不要恐怖氛围，不要血腥，不要过度写实，不要过强AI感，不要让钢琴场景和走廊场景断裂得太生硬，不要过快转场，不要手臂裸露，不要手表，不要画面里出现多余物体漂浮或奇怪变形。",
