      "phase": "商场 / 试衣间 / 钢琴",
      "prompt": "以这张图为基础生成视频。 第一视角，人物正坐在一架黑色三角钢琴前弹奏，镜头固定在演奏者胸口与眼睛之间的位置，正对琴键和乐谱。画面中央是摊开的旧乐谱，前方是钢琴内部与琴盖的结构，左右两只手自然放在琴键上，正在缓慢、克制地弹奏。 视频中，双手和手指要有细腻真实的弹琴动作： 手腕微微起伏，手指依次按下琴键，左右手节奏不同但协调，动作温柔、克制、连贯，不夸张，不炫技。演奏过程中，人物的身体有非常轻微的呼吸感，镜头也可以带一点极弱的自然呼吸式晃动，但整体仍然稳定安静。 环境氛围是灰白、安静、克制、略带哀伤的室内空间。 窗边的柔和自然光轻轻照进来，空气安静，花瓶中的花束、钢琴上的旧书、墙上的壁灯与挂画都保持稳定，仅允许有极轻微的静态环境呼吸感。 乐谱纸页可以有极轻微的细小颤动，像房间里有几乎感觉不到的空气流动。 钢琴琴键在按下时有明确反馈，黑白键的起伏自然准确。 整体节奏要慢，情绪要内敛， 画面具有电影感、细腻插画质感、柔和克制的动态效果，不要太写实，也不要强AI感。",
