      "phase": "婚礼",
      "prompt": "以图一为首帧，图二为尾帧。 第一视角，固定机位，正对钢琴，整体延续当前这种低饱和、柔和、复古、纸张水彩质感。 画面开始时，`我`已经弹完最后一个音，不再继续弹琴。双手还停留在琴键上片刻，空气安静下来。随后镜头出现非常轻微的颤动，像刚刚结束演奏后的喘息与余震感。 `我`的双手缓缓从琴键上收回，动作自然、克制、略带疲惫，像弹完一首很重要的曲子后终于松开力气。收手的同时，人物轻轻叹了一口气，情绪是安静的、低落的、带一点失去之后的空茫。 在`我`的手收起之后，画面右上方缓缓进入一只老人的手。老人的手动作很轻，很稳，不突兀，不惊悚。老人手里拿着一枚金色戒指，慢慢把戒指放到钢琴上，位置与尾帧一致。 整个过程节奏要慢，停顿要够，不要做成惊吓式出现，不要突然闪现。老人的手出现要自然，整体氛围温柔、安静、落寞，音乐已经停下，只剩呼吸、轻微衣料摩擦感，以及手放下戒指时触碰感。 最终自然过渡到图二的构图与状态。",
